  useEffect(() => {
    const frame = window.requestAnimationFrame(() => {
      if (abnahmeCustomerResultsRef.current) {
        abnahmeCustomerResultsRef.current.scrollTop = 0;
        abnahmeCustomerResultsRef.current.scrollLeft = 0;
      }
    });

    return () => window.cancelAnimationFrame(frame);
  }, [abnahmeCustomerSearch]);

  useEffect(() => {
    const frame = window.requestAnimationFrame(() => {
      if (abnahmeDeviceResultsRef.current) {
        abnahmeDeviceResultsRef.current.scrollTop = 0;
        abnahmeDeviceResultsRef.current.scrollLeft = 0;
      }
    });

    return () => window.cancelAnimationFrame(frame);
  }, [abnahmeDeviceSearch]);

  useEffect(() => {
    if (devices.length === 0) return;

    const params = new URLSearchParams(window.location.search);
    const deviceIdFromUrl = params.get("device");

    if (!deviceIdFromUrl) return;

    const foundDevice = devices.find(
      (item) => String(item.id) === deviceIdFromUrl,
    );

    if (foundDevice) {
      setActivePage("Geräte");
      setSelectedDeviceView(foundDevice);
    }
  }, [devices]);

  const customerNames = useMemo(() => {
    return customers
      .map((item) => item.company || "")
      .filter((item) => item.trim() !== "");
  }, [customers]);

  const filteredTickets = useMemo(() => {
    return tickets.filter((ticket) => {
      if (userProfile?.role === "customer") {
        const linkedCustomer = userProfile.customer_id
          ? customers.find((item) => item.id === userProfile.customer_id)
          : null;

        const belongsToCustomer =
          ticket.customer_id === userProfile.customer_id ||
          (!!linkedCustomer?.company &&
            ticket.customer === linkedCustomer.company);

        if (!belongsToCustomer) return false;
      }

      if (userProfile?.role === "technician") {
        const isAssignedToMe = ticket.assigned_to === userProfile.id;

        if (!isAssignedToMe) return false;
      }

      const search = searchTerm.trim();

      const linkedTicketCustomer =
        customers.find((item) => item.id === ticket.customer_id) ||
        customers.find((item) => getCustomerLabel(item) === ticket.customer) ||
        customers.find((item) => item.company === ticket.customer) ||
        null;

      const customerSearchText = linkedTicketCustomer
        ? getCustomerSearchText(linkedTicketCustomer)
        : "";

      const linkedTicketDevice =
        devices.find((item) => item.name === ticket.device) ||
        devices.find((item) => String(item.serial_number || "") === String(ticket.device || "")) ||
        null;

      const matchesSearch =
        !search ||
        matchesTrybunPrefixSearch(
          [
            ticket.ticket_number,
            ticket.customer,
            ticket.issue,
            ticket.device,
            linkedTicketDevice?.serial_number,
            linkedTicketDevice?.location,
            linkedTicketDevice?.manufacturer,
            getManufacturerNameById(linkedTicketDevice?.manufacturer_id),
            getDeviceModelNameById(linkedTicketDevice?.model_id),
            ticket.description,
            ticket.billing_customer_id,
            ticket.service_location_name,
            ticket.service_address,
            ticket.service_contact_name,
            ticket.service_contact_phone,
            ticket.service_contact_email,
            linkedTicketCustomer?.customer_number,
            linkedTicketCustomer?.supplier_number,
            linkedTicketCustomer?.contact_person,
            linkedTicketCustomer?.email,
            linkedTicketCustomer?.phone,
            linkedTicketCustomer?.city,
            customerSearchText,
          ],
          search,
        );

      const matchesStatus =
        statusFilter === "Alle" || ticket.status === statusFilter;

      const matchesPriority =
        priorityFilter === "Alle" || ticket.priority === priorityFilter;

      const matchesTicketFocus =
        ticketListFocus === "Alle" ||
        (() => {
          if (ticketListFocus !== "ServiceProof") return true;
          if (!["Abgeschlossen", "Erledigt"].includes(ticket.status || "")) return false;

          const hasTicketDocument = documents.some(
            (documentItem) => documentItem.ticket_id === ticket.id,
          );
          const hasCustomerConfirmation = Boolean(
            ticket.customer_signature ||
              ticket.customer_approval_name ||
              ticket.customer_approval_at,
          );

          return !(
            ticket.completed_at &&
            ticket.assigned_to &&
            ticket.service_report &&
            ticket.technician_signature &&
            hasCustomerConfirmation &&
            hasTicketDocument
          );
        })();

      return matchesSearch && matchesStatus && matchesPriority && matchesTicketFocus;
    });
  }, [
    tickets,
    customers,
    devices,
    manufacturers,
    deviceModels,
    userProfile,
    searchTerm,
    statusFilter,
    priorityFilter,
    ticketListFocus,
    documents,
  ]);



  const sortedTicketListTickets = searchTerm.trim()
    ? filteredTickets
        .slice()
        .sort((a, b) => {
          const linkedCustomerA =
            customers.find((item) => item.id === a.customer_id) ||
            customers.find((item) => item.company === a.customer) ||
            null;
          const linkedCustomerB =
            customers.find((item) => item.id === b.customer_id) ||
            customers.find((item) => item.company === b.customer) ||
            null;
          const linkedDeviceA =
            devices.find((item) => item.name === a.device) ||
            devices.find((item) => String(item.serial_number || "") === String(a.device || "")) ||
            null;
          const linkedDeviceB =
            devices.find((item) => item.name === b.device) ||
            devices.find((item) => String(item.serial_number || "") === String(b.device || "")) ||
            null;

          const query = searchTerm.trim();
          const rankDifference =
            getTrybunSearchRank(
              [
                [a.ticket_number, a.issue],
                [a.customer, linkedCustomerA?.company, linkedCustomerA ? getCustomerDisplayName(linkedCustomerA) : ""],
                [a.device, linkedDeviceA?.name, linkedDeviceA?.model],
                [linkedDeviceA?.serial_number],
                [a.service_location_name, a.service_contact_name],
                [a.description, a.service_address],
              ],
              query,
            ) -
            getTrybunSearchRank(
              [
                [b.ticket_number, b.issue],
                [b.customer, linkedCustomerB?.company, linkedCustomerB ? getCustomerDisplayName(linkedCustomerB) : ""],
                [b.device, linkedDeviceB?.name, linkedDeviceB?.model],
                [linkedDeviceB?.serial_number],
                [b.service_location_name, b.service_contact_name],
                [b.description, b.service_address],
              ],
              query,
            );

          if (rankDifference !== 0) return rankDifference;

          return new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime();
        })
    : sortTicketsByCreatedAtDesc(filteredTickets);

  const ticketListDisplayTickets =
    statusFilter === "Alle"
      ? sortedTicketListTickets
      : sortedTicketListTickets.slice(0, 5);

  const visibleRoleTickets = useMemo(() => {
    return tickets.filter((ticket) => {
      if (userProfile?.role === "customer") {
        const linkedCustomer = userProfile.customer_id
          ? customers.find((item) => item.id === userProfile.customer_id)
          : null;

        const belongsToCustomer =
          ticket.customer_id === userProfile.customer_id ||
          (!!linkedCustomer?.company && ticket.customer === linkedCustomer.company);

        return belongsToCustomer;
      }

      if (userProfile?.role === "technician") {
        return ticket.assigned_to === userProfile.id;
      }

      return true;
    });
  }, [tickets, customers, userProfile]);

  const ticketStats = useMemo(() => {
    const sourceTickets = visibleRoleTickets;

    return {
      total: sourceTickets.length,
      // "Offen" bedeutet in der Übersicht: Ticket ist noch nicht beendet.
      // Dadurch zählen auch bereits zugewiesene bzw. laufende Tickets als offen,
      // genau wie in Kalender und Einsatzplanung.
      open: sourceTickets.filter(
        (ticket) =>
          !["Abgeschlossen", "Erledigt", "Storniert"].includes(ticket.status || ""),
      ).length,
      assigned: sourceTickets.filter((ticket) => ticket.status === "Zugewiesen").length,
      inProgress: sourceTickets.filter((ticket) => ticket.status === "In Bearbeitung").length,
      waitingParts: sourceTickets.filter((ticket) => ticket.status === "Wartet auf Ersatzteile").length,
      completed: sourceTickets.filter(
        (ticket) =>
          ticket.status === "Abgeschlossen" || ticket.status === "Erledigt",
      ).length,
      active: sourceTickets.filter(
        (ticket) =>
          ticket.status !== "Abgeschlossen" &&
          ticket.status !== "Erledigt" &&
          ticket.status !== "Storniert",
      ).length,
      today: sourceTickets.filter(
        (ticket) => ticket.service_date === new Date().toISOString().split("T")[0],
      ).length,
    };
  }, [visibleRoleTickets]);

  const filteredDocuments = useMemo(() => {
    const search = documentSearchTerm.trim();

    const activeCompanyId = Number(
      companyData?.id || companyDataRef.current?.id || 0,
    );

    const tenantFilteredDocuments = activeCompanyId
      ? documents.filter(
          (item) =>
            item.company_id != null &&
            Number(item.company_id) === activeCompanyId,
        )
      : [];

    const customerFilteredDocuments =
      userProfile?.role === "customer"
        ? tenantFilteredDocuments.filter(
            (item) => item.customer_id === userProfile?.customer_id,
          )
        : tenantFilteredDocuments;

    return customerFilteredDocuments.filter((item) => {
      const linkedDevice = item.device_id
        ? devices.find((deviceItem) => deviceItem.id === item.device_id)
        : null;

      const linkedTicket = item.ticket_id
        ? tickets.find((ticketItem) => ticketItem.id === item.ticket_id)
        : null;

      const customerName = getDocumentCustomerName(item).toLowerCase();
      const deviceName = getDeviceNameById(item.device_id).toLowerCase();
      const ticketNumber = getDocumentTicketNumber(item).toLowerCase();

      const matchesCategory =
        activeDocumentCategory === "Alle" || item.category === activeDocumentCategory;

      const matchesCustomer =
        documentCustomerFilter === "Alle" ||
        String(item.customer_id || linkedDevice?.customer_id || linkedTicket?.customer_id || "") ===
          documentCustomerFilter;

      const matchesDevice =
        documentDeviceFilter === "Alle" || String(item.device_id || "") === documentDeviceFilter;

      const matchesSearch =
        !search ||
        matchesTrybunPrefixSearch(
          [
            item.file_name,
            item.category,
            customerName,
            deviceName,
            ticketNumber,
            linkedTicket?.issue,
          ],
          search,
        );

      const matchesQuickFilter = (() => {
        if (documentQuickFilter === "Alle") return true;
        if (item.category !== "Abnahmeprotokolle") return false;

        const createdDate = item.created_at ? new Date(item.created_at) : null;
        const nextDate = item.next_inspection_date ? new Date(item.next_inspection_date) : null;
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        if (documentQuickFilter === "Dieser Monat") {
          if (!createdDate) return false;
          const now = new Date();
          return createdDate.getFullYear() === now.getFullYear() && createdDate.getMonth() === now.getMonth();
        }

        if (!nextDate) return false;
        nextDate.setHours(0, 0, 0, 0);
        const diffDays = Math.ceil((nextDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

        if (documentQuickFilter === "Bald fällig") return diffDays >= 0 && diffDays <= 30;
        if (documentQuickFilter === "Überfällig") return nextDate.getTime() < today.getTime();

        return true;
      })();

      return matchesCategory && matchesCustomer && matchesDevice && matchesSearch && matchesQuickFilter;
    })
    .sort((a, b) => {
      if (search) {
        const linkedTicketA = a.ticket_id
          ? tickets.find((item) => item.id === a.ticket_id)
          : null;
        const linkedTicketB = b.ticket_id
          ? tickets.find((item) => item.id === b.ticket_id)
          : null;

        const rankDifference =
          getTrybunSearchRank(
            [
              [a.file_name],
              [a.category],
              [getDocumentCustomerName(a), getDeviceNameById(a.device_id)],
              [getDocumentTicketNumber(a), linkedTicketA?.issue],
            ],
            search,
          ) -
          getTrybunSearchRank(
            [
              [b.file_name],
              [b.category],
              [getDocumentCustomerName(b), getDeviceNameById(b.device_id)],
              [getDocumentTicketNumber(b), linkedTicketB?.issue],
            ],
            search,
          );

        if (rankDifference !== 0) return rankDifference;
      }

      return String(b.created_at || "").localeCompare(String(a.created_at || ""));
    });
  }, [
    documents,
    devices,
    tickets,
    activeDocumentCategory,
    documentSearchTerm,
    documentQuickFilter,
    documentCustomerFilter,
    documentDeviceFilter,
    userProfile,
    companyData,
  ]);

  const inspectionStats = useMemo(() => {
    const ok = devices.filter(
      (item) => getInspectionStatus(item.next_check).label === "Gültig",
    ).length;

    const soon = devices.filter(
      (item) => getInspectionStatus(item.next_check).label === "Bald fällig",
    ).length;

    const overdue = devices.filter(
      (item) => getInspectionStatus(item.next_check).label === "Überfällig",
    ).length;

    const missing = devices.filter(
      (item) => getInspectionStatus(item.next_check).label === "Kein Datum",
    ).length;

    return { ok, soon, overdue, missing };
  }, [devices]);


  function getMaintenanceDueState(plan: MaintenancePlan) {
    if (!plan.next_due) {
      return { label: "Ohne Termin", className: "bg-slate-100 text-slate-700", days: 9999 };
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const dueDate = new Date(plan.next_due);
    dueDate.setHours(0, 0, 0, 0);

    const days = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

    if (days < 0) {
      return { label: `${Math.abs(days)} Tag(e) überfällig`, className: "bg-red-100 text-red-700", days };
    }

    if (days === 0) {
      return { label: "Heute fällig", className: "bg-orange-100 text-orange-700", days };
    }

    if (days <= 7) {
      return { label: `in ${days} Tag(en) fällig`, className: "bg-amber-100 text-amber-700", days };
    }

    return { label: `in ${days} Tag(en)`, className: "bg-emerald-100 text-emerald-700", days };
  }

  const maintenancePremiumStats = useMemo(() => {
    const activePlans = maintenancePlans.filter(
      (plan) => String(plan.status || "").toLowerCase() !== "abgeschlossen",
    );

    return {
      total: activePlans.length,
      dueToday: activePlans.filter((plan) => getMaintenanceDueState(plan).days === 0).length,
      dueSoon: activePlans.filter((plan) => {
        const days = getMaintenanceDueState(plan).days;
        return days > 0 && days <= 7;
      }).length,
      overdue: activePlans.filter((plan) => getMaintenanceDueState(plan).days < 0).length,
    };
  }, [maintenancePlans]);

  const maintenanceTicketSuggestions = useMemo(() => {
    return maintenancePlans
      .filter((plan) => String(plan.status || "").toLowerCase() !== "abgeschlossen")
      .filter((plan) => getMaintenanceDueState(plan).days <= 7)
      .sort((a, b) => getMaintenanceDueState(a).days - getMaintenanceDueState(b).days)
      .slice(0, 20);
  }, [maintenancePlans]);

  const technicianPremiumTickets = useMemo(() => {
    if (userProfile?.role === "customer") return [];

    return sortTicketsByAppointment(
      visibleRoleTickets.filter((ticket) => {
        if (["Abgeschlossen", "Erledigt", "Storniert"].includes(ticket.status || "")) return false;

        if (userProfile?.role === "technician") {
          return ticket.assigned_to === userProfile?.id;
        }

        return true;
      }),
    );
  }, [visibleRoleTickets, userProfile?.role, userProfile?.id]);

  const technicianPremiumTodayTickets = useMemo(() => {
    return technicianPremiumTickets.filter((ticket) => ticket.service_date === new Date().toISOString().split("T")[0]);
  }, [technicianPremiumTickets]);

  const technicianPremiumOverdueTickets = useMemo(() => {
    return technicianPremiumTickets.filter((ticket) => {
      if (!ticket.service_date) return false;
      return ticket.service_date < new Date().toISOString().split("T")[0];
    });
  }, [technicianPremiumTickets]);

  const technicianPremiumWeekTickets = useMemo(() => {
    const today = new Date(new Date().toISOString().split("T")[0]);
    const weekEnd = new Date(today);
    weekEnd.setDate(weekEnd.getDate() + 7);

    return technicianPremiumTickets.filter((ticket) => {
      if (!ticket.service_date) return false;
      const serviceDate = new Date(ticket.service_date);
      serviceDate.setHours(0, 0, 0, 0);
      return serviceDate >= today && serviceDate <= weekEnd;
    });
  }, [technicianPremiumTickets]);

  // Alle noch aktiven Tickets mit einem Einsatztermin. Anders als "Heute" zeigt diese
  // Zahl damit auch einen bereits geplanten Termin in der Zukunft (z. B. T-7187).
  const technicianPremiumPlannedTickets = useMemo(() => {
    return technicianPremiumTickets.filter((ticket) => Boolean(ticket.service_date));
  }, [technicianPremiumTickets]);

  const technicianPremiumMaintenancePlans = useMemo(() => {
    return maintenanceTicketSuggestions.filter((plan) => {
      if (userProfile?.role === "technician") return plan.assigned_to === userProfile?.id;
      return true;
    });
  }, [maintenanceTicketSuggestions, userProfile?.role, userProfile?.id]);

  function getTicketCustomerContactPremium(ticket: Ticket) {
    const relatedCustomer = getCustomerForTicket(ticket);
    const relatedDevice = getDeviceForTicket(ticket);

    return {
      customer: relatedCustomer,
      phone: ticket.service_contact_phone || relatedCustomer?.phone || "",
      email: ticket.service_contact_email || relatedCustomer?.email || "",
      address:
        ticket.service_address ||
        (relatedCustomer ? buildCustomerAddress(relatedCustomer) : "") ||
        relatedDevice?.location ||
        "",
    };
  }

  function openNavigationForTicketPremium(ticket: Ticket) {
    const contact = getTicketCustomerContactPremium(ticket);

    if (!contact.address) {
      alert("Keine Adresse für Navigation gefunden.");
      return;
    }

    window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(contact.address)}`, "_blank");
  }

  async function quickTechnicianStatusPremium(ticket: Ticket, nextStatus: string) {
    if (userProfile?.role !== "admin" && userProfile?.role !== "technician") {
      alert("Nur Admins und Techniker können den Einsatzstatus ändern.");
      return;
    }

    await updateTicketStatus(ticket.id, nextStatus);

    await createDeviceHistory(
      getDeviceForTicket(ticket)?.id || null,
      `Technikerstatus: ${nextStatus}`,
      `${ticket.ticket_number || "Ticket"} · ${ticket.issue || "Einsatz"}`,
      "Einsatz",
    );
  }

  function buildTechnicianChecklistPremium(ticket: Ticket) {
    const documentsCount = getDocumentsForTicket(ticket).length;
    const hasReport = Boolean(ticket.service_report);
    const hasSignatures = Boolean(ticket.technician_signature || ticket.customer_signature);

    return [
      { label: "Ankunft bestätigt", done: ["Vor Ort", "In Bearbeitung", "Abgeschlossen"].includes(ticket.status) },
      { label: "Sichtprüfung / Funktionstest", done: ["In Bearbeitung", "Abgeschlossen"].includes(ticket.status) },
      { label: "Fotos / Nachweise vorhanden", done: documentsCount > 0 },
      { label: "Servicebericht erstellt", done: hasReport },
      { label: "Unterschrift vorhanden", done: hasSignatures },
      { label: "Einsatz abgeschlossen", done: ticket.status === "Abgeschlossen" },
    ];
  }

  const emailStatusStats = useMemo(() => {
    return {
      pending: notifications.filter((item) => (item.email_status || item.status || "").toLowerCase() === "pending").length,
      queued: notifications.filter((item) => (item.email_status || item.status || "").toLowerCase() === "queued").length,
      sent: notifications.filter((item) => (item.email_status || item.status || "").toLowerCase() === "sent").length,
      failed: notifications.filter((item) => (item.email_status || item.status || "").toLowerCase() === "failed").length,
    };
  }, [notifications]);


  const ticketChatUnreadCount = useMemo(() => {
    return ticketChatMessages.filter((message) => {
      if (userProfile?.role === "customer") return !message.read_by_customer;
      if (userProfile?.role === "technician") return !message.read_by_technician;
      return !message.read_by_admin;
    }).length;
  }, [ticketChatMessages, userProfile?.role]);

  function getTicketChatMessages(ticketId: number) {
    return ticketChatMessages
      .filter((message) => message.ticket_id === ticketId)
      .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
  }

  function getTicketChatUnreadCount(ticketId: number) {
    return getTicketChatMessages(ticketId).filter((message) => {
      if (userProfile?.role === "customer") return !message.read_by_customer;
      if (userProfile?.role === "technician") return !message.read_by_technician;
      return !message.read_by_admin;
    }).length;
  }

  const communicationFilteredNotifications = useMemo(() => {
    const search = communicationSearchTerm.trim();

    return notifications.filter((item) => {
      const statusValue = String(item.email_status || item.status || "pending").toLowerCase();

      const matchesStatus =
        communicationStatusFilter === "Alle" ||
        (communicationStatusFilter === "Ausstehend" && ["pending", "queued", "geplant", "vorgemerkt"].includes(statusValue)) ||
        (communicationStatusFilter === "Gesendet" && ["sent", "gesendet"].includes(statusValue)) ||
        (communicationStatusFilter === "Fehler" && ["failed", "fehler"].includes(statusValue));

      const matchesType = communicationTypeFilter === "Alle" || item.type === communicationTypeFilter;

      const matchesSearch =
        !search ||
        matchesTrybunPrefixSearch(
          [
            item.type,
            item.recipient,
            item.subject,
            item.message,
            item.email_status,
            item.status,
            item.email_error,
            item.email_template,
            item.email_provider_id,
            tickets.find((ticket) => ticket.id === item.related_ticket_id)?.ticket_number,
          ],
          search,
        );

      return matchesStatus && matchesType && matchesSearch;
    })
    .sort((a, b) => {
      if (search) {
        const ticketA = tickets.find((ticket) => ticket.id === a.related_ticket_id);
        const ticketB = tickets.find((ticket) => ticket.id === b.related_ticket_id);

        const rankDifference =
          getTrybunSearchRank(
            [
              [a.subject],
              [a.recipient],
              [a.type],
              [ticketA?.ticket_number],
              [a.message, a.email_status, a.status, a.email_error],
            ],
            search,
          ) -
          getTrybunSearchRank(
            [
              [b.subject],
              [b.recipient],
              [b.type],
              [ticketB?.ticket_number],
              [b.message, b.email_status, b.status, b.email_error],
            ],
            search,
          );

        if (rankDifference !== 0) return rankDifference;
      }

      return String(b.created_at || "").localeCompare(String(a.created_at || ""));
    });
  }, [notifications, communicationStatusFilter, communicationTypeFilter, communicationSearchTerm, tickets]);

  const communicationTypes = useMemo(() => {
    return Array.from(new Set(notifications.map((item) => item.type).filter(Boolean))).sort();
  }, [notifications]);

  const communicationLiveStats = useMemo(() => {
    return {
      total: notifications.length,
      visible: communicationFilteredNotifications.length,
      pending: emailStatusStats.pending + emailStatusStats.queued,
      sent: emailStatusStats.sent,
      failed: emailStatusStats.failed,
    };
  }, [notifications.length, communicationFilteredNotifications.length, emailStatusStats]);

  const newUserNameCandidates = useMemo<CustomerPortalPersonCandidate[]>(() => {
    if (newUserRole !== "customer") return [];

    const search = newUserFullName.trim();
    if (!search) return [];

    const candidates: CustomerPortalPersonCandidate[] = [];
    const seen = new Set<string>();

    const addCandidate = (
      customer: Customer,
      slot: string,
      rawName?: string | null,
      rawEmail?: string | null,
    ) => {
      const name = String(rawName || "").trim();
      if (!name) return;

      const key = `${customer.id}:${slot}:${name.toLocaleLowerCase("de-DE")}`;
      if (seen.has(key)) return;
      seen.add(key);

      candidates.push({
        key,
        customerId: Number(customer.id),
        name,
        email: String(rawEmail || "").trim(),
        customerLabel: getCustomerLabel(customer),
        company: String(customer.company || "").trim(),
        customerNumber: String(customer.customer_number || "").trim(),
      });
    };

    customers.forEach((customer) => {
      const fullName = `${customer.first_name || ""} ${customer.last_name || ""}`.trim();
      addCandidate(customer, "primary", fullName, customer.email);

      if (normalizeCompareText(customer.contact_person) !== normalizeCompareText(fullName)) {
        addCandidate(customer, "contact-person", customer.contact_person, customer.email);
      }

      addCandidate(customer, "contact-1", customer.contact_1_name, customer.contact_1_email);
      addCandidate(customer, "contact-2", customer.contact_2_name, customer.contact_2_email);
    });

    return candidates
      .filter((candidate) => matchesTrybunPrefixSearch([candidate.name], search))
      .sort((a, b) => {
        const rankDifference =
          getTrybunSearchRank([[a.name]], search) - getTrybunSearchRank([[b.name]], search);
        if (rankDifference !== 0) return rankDifference;
        return a.name.localeCompare(b.name, "de");
      })
      .slice(0, 20);
  }, [customers, newUserFullName, newUserRole]);

  function selectNewUserCustomerPerson(candidate: CustomerPortalPersonCandidate) {
    setNewUserFullName(candidate.name);
    setNewUserCustomerId(String(candidate.customerId));
    setNewUserSelectedPersonKey(candidate.key);
    setNewUserNameSearchOpen(false);

    if (candidate.email) {
      setNewUserEmail(candidate.email);
    }
  }

  const userManagementStats = useMemo(() => {
    return {
      total: userProfiles.length,
      admins: userProfiles.filter((profile) => profile.role === "admin").length,
      technicians: userProfiles.filter((profile) => profile.role === "technician").length,
      customers: userProfiles.filter((profile) => profile.role === "customer").length,
      active: userProfiles.filter((profile) => profile.is_active !== false).length,
      inactive: userProfiles.filter((profile) => profile.is_active === false).length,
    };
  }, [userProfiles]);

  const userManagementProfiles = useMemo(() => {
    const search = userManagementSearch.trim();

    return userProfiles
      .filter((profile) => profile.role === userManagementRoleFilter)
      // Kunden erscheinen hier nur als echte Portal-Zugänge aus profiles.
      // Reine Servicekunden aus customers werden niemals in diese Liste gemischt.
      .filter((profile) => {
        if (!search) return true;
        const linkedCustomer = profile.role === "customer" ? getCustomerForUserProfile(profile) : null;
        return matchesTrybunPrefixSearch(
          [
            getUserDisplayName(profile),
            profile.company,
            userCompanyNames[profile.id],
            linkedCustomer?.company,
            linkedCustomer?.email,
            linkedCustomer?.customer_number,
          ],
          search,
        );
      })
      .sort((a, b) => {
        if (search) {
          const linkedCustomerA = a.role === "customer" ? getCustomerForUserProfile(a) : null;
          const linkedCustomerB = b.role === "customer" ? getCustomerForUserProfile(b) : null;

          const rankDifference =
            getTrybunSearchRank(
              [
                [getUserDisplayName(a)],
                [a.company, userCompanyNames[a.id]],
                [linkedCustomerA?.company, linkedCustomerA?.customer_number],
                [linkedCustomerA?.email],
              ],
              search,
            ) -
            getTrybunSearchRank(
              [
                [getUserDisplayName(b)],
                [b.company, userCompanyNames[b.id]],
                [linkedCustomerB?.company, linkedCustomerB?.customer_number],
                [linkedCustomerB?.email],
              ],
              search,
            );

          if (rankDifference !== 0) return rankDifference;
        }

        return getUserDisplayName(a).localeCompare(getUserDisplayName(b), "de");
      });
  }, [userProfiles, userManagementRoleFilter, userManagementSearch, userCompanyNames, customers]);

  const notificationTotalPages = Math.max(1, Math.ceil(communicationFilteredNotifications.length / notificationPageSize));

  const visibleNotifications = useMemo(() => {
    const startIndex = (notificationPage - 1) * notificationPageSize;
    return communicationFilteredNotifications.slice(startIndex, startIndex + notificationPageSize);
  }, [communicationFilteredNotifications, notificationPage]);


  function getEmailStatusLabel(status?: string | null) {
    const value = String(status || "pending").toLowerCase();

    if (value === "sent") return "Gesendet";
    if (value === "failed") return "Fehler";
    if (value === "queued") return "Vorgemerkt";
    if (value === "draft") return "Entwurf";

    return "Ausstehend";
  }

  function getEmailStatusClass(status?: string | null) {
    const value = String(status || "pending").toLowerCase();

    if (value === "sent") return "bg-emerald-500/15 text-emerald-300 border-emerald-500/30";
    if (value === "failed") return "bg-red-500/15 text-red-300 border-red-500/30";
    if (value === "queued") return "bg-blue-500/15 text-blue-300 border-blue-500/30";

    return "bg-amber-500/15 text-amber-300 border-amber-500/30";
  }


  function formatDateTime(value?: string | null) {
    if (!value) return "—";

    try {
      return new Intl.DateTimeFormat("de-DE", {
        dateStyle: "short",
        timeStyle: "short",
      }).format(new Date(value));
    } catch {
      return value;
    }
  }

  function formatServiceDate(value?: string | null) {
    if (!value) return "";
    const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return String(value);
    return `${match[3]}.${match[2]}.${match[1]}`;
  }

  function formatServiceTime(value?: string | null) {
    if (!value) return "";
    const match = String(value).match(/^(\d{2}):(\d{2})/);
    if (!match) return String(value);
    return `${match[1]}:${match[2]} Uhr`;
  }

  function formatServiceAppointment(date?: string | null, time?: string | null) {
    if (!date) return "Kein Termin geplant";
    const formattedDate = formatServiceDate(date);
    const formattedTime = formatServiceTime(time);
    return formattedTime ? `${formattedDate} · ${formattedTime}` : formattedDate;
  }

  function isCustomerPortalDocument(documentItem: DocumentItem) {
    return String(documentItem.file_path || "").includes("kundenportal/");
  }

  function getDocumentPremiumKind(documentItem: DocumentItem) {
    const name = String(documentItem.file_name || "").toLowerCase();
    const category = String(documentItem.category || "").toLowerCase();

    if (category.includes("video") || /\.(mp4|mov|webm|m4v|avi)$/i.test(name)) return "Video";
    if (category.includes("foto") || category.includes("bild") || /\.(jpg|jpeg|png|webp|heic|gif)$/i.test(name)) return "Foto";
    if (category.includes("lieferschein")) return "Lieferschein";
    if (/\.pdf$/i.test(name)) return "PDF";

    return "Dokument";
  }

  function getDocumentPremiumClass(documentItem: DocumentItem) {
    const kind = getDocumentPremiumKind(documentItem);

    if (isCustomerPortalDocument(documentItem)) {
      return "border-emerald-200 bg-emerald-50";
    }

    if (kind === "Foto") return "border-sky-200 bg-sky-50";
    if (kind === "Video") return "border-purple-200 bg-purple-50";
    if (kind === "Lieferschein") return "border-amber-200 bg-amber-50";

    return "border-slate-200 bg-white";
  }

  async function checkSession() {
    const { data } = await supabase.auth.getSession();

    setSession(data.session);
    setAuthLoading(false);

    if (data.session) {
      setAppDataLoaded(false);
      const profileIsValid = await loadUserProfile(data.session.user.id);

      if (profileIsValid) {
        loadApplicationData();
      }
    } else {
      setProfileLoading(false);
      setAppDataLoaded(false);
    }
  }

  async function loadCompany(userIdOverride?: string) {
    const userId = userIdOverride || session?.user?.id;
    const stableCompany =
      companyDataRef.current ||
      readCachedCompanyData(userId);

    if (isOfflineRuntime()) {
      if (stableCompany?.id && !companyDataRef.current) {
        commitCompanyData(stableCompany, userId);
      }
      return stableCompany;
    }

    if (!userId) {
      const preservedCompany = companyDataRef.current;

      if (preservedCompany?.id) {
        return preservedCompany;
      }

      return null;
    }

    try {
      const { data: memberships, error: memberError } = await supabase
        .from("company_members")
        .select("company_id, role, created_at")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });

      if (!memberError) {
        const companyIds = (memberships || [])
          .map((member: any) => Number(member.company_id))
          .filter((companyId: number) => Number.isFinite(companyId) && companyId > 0);

        if (companyIds.length > 0) {
          const { data: companiesResult, error: companyError } = await supabase
            .from("companies")
            .select("*")
            .in("id", companyIds)
            .eq("is_active", true);

          if (!companyError) {
            const companiesList = (companiesResult || []) as CompanyData[];

            if (companiesList.length > 0) {
              const preferredCompany =
                companiesList.find((company) => company.id === companyIds[0]) ||
                companiesList[0];

              commitCompanyData(preferredCompany, userId);
              return preferredCompany;
            }
          } else {
            console.error(
              "Firma konnte über Mitgliedschaft nicht geladen werden:",
              companyError.message,
            );
          }
        }
      } else {
        console.error(
          "Firmenmitgliedschaft konnte nicht geladen werden:",
          memberError.message,
        );
      }

      const profileCompanyName = String(userProfile?.company || "").trim();

      if (profileCompanyName) {
        const { data: fallbackCompany, error: fallbackError } = await supabase
          .from("companies")
          .select("*")
          .eq("name", profileCompanyName)
          .eq("is_active", true)
          .maybeSingle();

        if (!fallbackError && fallbackCompany?.id) {
          commitCompanyData(fallbackCompany as CompanyData, userId);
          return fallbackCompany as CompanyData;
        }

        if (fallbackError) {
          console.error(
            "Firma konnte über Profil-Fallback nicht geladen werden:",
            fallbackError.message,
          );
        }
      }

      if (userProfile?.customer_id) {
        const { data: customerCompany, error: customerCompanyError } = await supabase
          .from("customers")
          .select("company_id")
          .eq("id", userProfile.customer_id)
          .maybeSingle();

        if (!customerCompanyError && customerCompany?.company_id) {
          const { data: portalCompany, error: portalCompanyError } = await supabase
            .from("companies")
            .select("*")
            .eq("id", customerCompany.company_id)
            .eq("is_active", true)
            .maybeSingle();

          if (!portalCompanyError && portalCompany?.id) {
            commitCompanyData(portalCompany as CompanyData, userId);
            return portalCompany as CompanyData;
          }
        }
      }

      // Wichtig: Bei einem kurzfristigen Auth-/RLS-/Netzwerkproblem darf das bereits
      // bestätigte Firmenbranding niemals auf TRYBUN-Standard zurückspringen.
      if (stableCompany?.id) {
        if (!companyDataRef.current) {
          commitCompanyData(stableCompany, userId);
        }
        return stableCompany;
      }

      return null;
    } catch (error) {
      console.error("Company-Ladevorgang fehlgeschlagen:", error);

      if (stableCompany?.id) {
        if (!companyDataRef.current) {
          commitCompanyData(stableCompany, userId);
        }
        return stableCompany;
      }

      return null;
    }
  }

  function applyServiceProfilePreset(profileKey: ServiceProfileKey) {
    setServiceProfileInput(profileKey);

    const preset =
      SERVICE_PROFILE_PRESETS.find((item) => item.key === profileKey) ||
      SERVICE_PROFILE_PRESETS[0];

    if (profileKey !== "custom") {
      setServiceTerminologyInput({ ...preset.terminology });
    }
  }

  function updateServiceTerminologyField(
    field: keyof ServiceTerminology,
    value: string,
  ) {
    setServiceTerminologyInput((current) => ({
      ...current,
      [field]: value,
    }));
  }

  function createServiceCustomFieldId(label: string) {
    const normalized = label
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 42);

    const base = normalized || "feld";
    let candidate = base;
    let suffix = 2;

    while (serviceCustomFieldsInput.some((field) => field.id === candidate)) {
      candidate = `${base}_${suffix}`;
      suffix += 1;
    }

    return candidate;
  }

  function addServiceCustomField() {
    const label = newServiceCustomFieldLabel.trim();

    if (!label) {
      alert("Bitte einen Feldnamen eingeben.");
      return;
    }

    const options =
      newServiceCustomFieldType === "select"
        ? newServiceCustomFieldOptions
            .split(",")
            .map((item) => item.trim())
            .filter(Boolean)
        : [];

    if (newServiceCustomFieldType === "select" && options.length < 2) {
      alert("Für ein Auswahlfeld bitte mindestens zwei Werte mit Komma getrennt eingeben.");
      return;
    }

    setServiceCustomFieldsInput((current) => [
      ...current,
      {
        id: createServiceCustomFieldId(label),
        label,
        type: newServiceCustomFieldType,
        unit: newServiceCustomFieldUnit.trim() || undefined,
        required: newServiceCustomFieldRequired,
        options: options.length > 0 ? options : undefined,
      },
    ]);

    setNewServiceCustomFieldLabel("");
    setNewServiceCustomFieldType("text");
    setNewServiceCustomFieldUnit("");
    setNewServiceCustomFieldRequired(false);
    setNewServiceCustomFieldOptions("");
  }

  function removeServiceCustomField(fieldId: string) {
    const field = serviceCustomFieldsInput.find((item) => item.id === fieldId);
    if (!field) return;

    if (!confirm(`Zusatzfeld "${field.label}" entfernen? Bereits gespeicherte Gerätewerte bleiben intern erhalten, werden aber nicht mehr angezeigt.`)) {
      return;
    }

    setServiceCustomFieldsInput((current) =>
      current.filter((item) => item.id !== fieldId),
    );
  }

  async function saveServiceCustomFields() {
    if (!isAdmin) {
      alert("Nur Admins können Zusatzfelder verwalten.");
      return;
    }

    const currentCompany = companyData || (await loadCompany(session?.user?.id));

    if (!currentCompany?.id) {
      alert("Keine Firma geladen. Bitte Seite neu laden.");
      return;
    }

    setServiceCustomFieldsSaving(true);

    const { data, error } = await supabase
      .from("companies")
      .update({ service_custom_fields: serviceCustomFieldsInput })
      .eq("id", currentCompany.id)
      .select("*")
      .maybeSingle();

    setServiceCustomFieldsSaving(false);

    if (error) {
      alert(`Zusatzfelder konnten nicht gespeichert werden: ${error.message}`);
      return;
    }

    commitCompanyData(
      (data || {
        ...currentCompany,
        service_custom_fields: serviceCustomFieldsInput,
      }) as CompanyData,
      session?.user?.id,
    );
    alert("Zusatzfelder gespeichert.");
  }

  async function saveSelectedDeviceCustomValues() {
    if (!selectedDeviceView || !(isAdmin || isTechnician)) return;

    const missingRequiredField = serviceCustomFieldsInput.find(
      (field) =>
        field.required &&
        !String(deviceCustomValues[field.id] || "").trim(),
    );

    if (missingRequiredField) {
      alert(`Bitte Pflichtfeld "${missingRequiredField.label}" ausfüllen.`);
      return;
    }

    const currentCompany = companyData || (await loadCompany(session?.user?.id));

    if (!currentCompany?.id) {
      alert("Ihre Firmenzuordnung konnte nicht geladen werden.");
      return;
    }

    setDeviceCustomValuesSaving(true);

    const { data, error } = await supabase
      .from("devices")
      .update({ custom_values: deviceCustomValues })
      .eq("id", selectedDeviceView.id)
      .eq("company_id", currentCompany.id)
      .select("*")
      .maybeSingle();

    setDeviceCustomValuesSaving(false);

    if (error) {
      alert(`Zusatzdaten konnten nicht gespeichert werden: ${error.message}`);
      return;
    }

    const updatedDevice = (data || {
      ...selectedDeviceView,
      custom_values: deviceCustomValues,
    }) as Device;

    setSelectedDeviceView(updatedDevice);
    setDevices((current) =>
      current.map((item) =>
        item.id === updatedDevice.id ? updatedDevice : item,
      ),
    );
    setDeviceCustomValuesEditing(false);

    await createDeviceHistory(
      updatedDevice.id,
      "Zusatzdaten aktualisiert",
      "Betriebsspezifische Gerätedaten wurden aktualisiert.",
      "Gerät",
    );
  }

  function createServiceTemplateId(name: string) {
    const normalized = name
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 42);

    const base = normalized || "vorlage";
    let candidate = base;
    let suffix = 2;

    while (serviceTemplatesInput.some((template) => template.id === candidate)) {
      candidate = `${base}_${suffix}`;
      suffix += 1;
    }

    return candidate;
  }

  function addServiceTemplate() {
    const name = newServiceTemplateName.trim();

    if (!name) {
      alert("Bitte einen Vorlagennamen eingeben.");
      return;
    }

    if (
      serviceTemplatesInput.some(
        (template) =>
          template.name.trim().toLowerCase() === name.toLowerCase() &&
          template.kind === newServiceTemplateKind,
      )
    ) {
      alert("Eine Vorlage mit diesem Namen existiert bereits.");
      return;
    }

    const checklist =
      newServiceTemplateKind === "inspection"
        ? newServiceTemplateChecklist
            .split("\n")
            .map((item) => item.trim())
            .filter(Boolean)
        : [];

    if (newServiceTemplateKind === "inspection" && checklist.length === 0) {
      alert("Bitte mindestens einen Prüfpunkt eingeben.");
      return;
    }

    const intervalDays =
      newServiceTemplateKind === "maintenance"
        ? Math.max(1, Number(newServiceTemplateIntervalDays) || 365)
        : null;

    setServiceTemplatesInput((current) => [
      ...current,
      {
        id: createServiceTemplateId(name),
        name,
        kind: newServiceTemplateKind,
        checklist: checklist.length > 0 ? checklist : undefined,
        interval_days: intervalDays,
      },
    ]);

    setNewServiceTemplateName("");
    setNewServiceTemplateChecklist("");
    setNewServiceTemplateIntervalDays("365");
  }

  function removeServiceTemplate(templateId: string) {
    const template = serviceTemplatesInput.find((item) => item.id === templateId);
    if (!template) return;

    if (!confirm(`Vorlage "${template.name}" entfernen? Bestehende Protokolle und Wartungspläne bleiben erhalten.`)) {
      return;
    }

    setServiceTemplatesInput((current) =>
      current.filter((item) => item.id !== templateId),
    );
  }

