  async function loadCustomers() {
    if (isOfflineRuntime()) return;

    const currentCompany = await resolveActiveCompanyForOperation();
    if (!currentCompany?.id) {
      setCustomers([]);
      return;
    }

    const pageSize = 1000;
    let from = 0;
    let loadedCustomers: Customer[] = [];

    while (true) {
      const to = from + pageSize - 1;

      let query = supabase
        .from("customers")
        .select("*")
        .eq("company_id", currentCompany.id)
        .order("created_at", { ascending: false })
        .range(from, to);

      if (userProfile?.role === "customer" && userProfile.customer_id) {
        query = query.eq("id", userProfile.customer_id);
      }

      const { data, error } = await query;

      if (error) {
        console.error("Kunden konnten nicht geladen werden:", error.message);
        setCustomers(loadedCustomers);
        return;
      }

      const batch = ((data || []) as Customer[]).filter(
        (item) => Number(item.company_id) === Number(currentCompany.id),
      );
      loadedCustomers = [...loadedCustomers, ...batch];

      if (batch.length < pageSize) break;
      from += pageSize;

      if (from > 50000) {
        console.warn("Kunden-Ladevorgang wurde zur Sicherheit bei 50.000 Datensätzen gestoppt.");
        break;
      }
    }

    setCustomers(loadedCustomers);
  }

  async function resolveCatalogUserRole(): Promise<"admin" | "technician" | "customer" | null> {
    // React-State kann direkt nach Login noch aus dem vorherigen Render stammen.
    // Deshalb wird die Rolle für den Stammdatenkatalog bei Bedarf direkt aus dem
    // aktuell authentifizierten Supabase-Benutzer ermittelt.
    if (
      userProfile?.role === "admin" ||
      userProfile?.role === "technician" ||
      userProfile?.role === "customer"
    ) {
      return userProfile.role;
    }

    const { data: authData, error: authError } = await supabase.auth.getUser();

    if (authError || !authData.user?.id) {
      console.error(
        "Rolle für Stammdatenkatalog konnte nicht aus Auth ermittelt werden:",
        authError?.message,
      );
      return null;
    }

    const { data: profileData, error: profileError } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", authData.user.id)
      .maybeSingle();

    if (profileError) {
      console.error(
        "Rolle für Stammdatenkatalog konnte nicht aus Profil ermittelt werden:",
        profileError.message,
      );
      return null;
    }

    const role = String(profileData?.role || "");

    if (role === "admin" || role === "technician" || role === "customer") {
      return role;
    }

    return null;
  }

  async function loadManufacturers() {
    if (isOfflineRuntime()) return;

    // Kunden laden den reinen Lesekatalog über eine SECURITY-DEFINER-RPC.
    // Die Funktion ermittelt die Firmen-ID ausschließlich aus auth.uid() -> profile -> customer
    // und gibt damit nur Hersteller der eigenen Servicefirma zurück.
    const catalogRole = await resolveCatalogUserRole();

    if (catalogRole === "customer") {
      const { data, error } = await supabase.rpc("customer_manufacturers_catalog");

      if (error) {
        console.error("Kunden-Herstellerkatalog konnte nicht geladen werden:", error.message);
        setManufacturers([]);
        return;
      }

      setManufacturers(((data || []) as Manufacturer[]).slice().sort((a, b) =>
        String(a.name || "").localeCompare(String(b.name || ""), "de"),
      ));
      return;
    }

    const currentCompany = await resolveActiveCompanyForOperation();
    if (!currentCompany?.id) {
      setManufacturers([]);
      return;
    }

    const { data, error } = await supabase
      .from("manufacturers")
      .select("*")
      .eq("company_id", currentCompany.id)
      .order("name", { ascending: true });

    if (error) {
      console.error("manufacturers konnten nicht mandantensicher geladen werden:", error.message);
      setManufacturers([]);
      return;
    }

    setManufacturers(
      ((data || []) as Manufacturer[]).filter(
        (item) => Number(item.company_id) === Number(currentCompany.id),
      ),
    );
  }

