  async function loadVoidedPartUsages(limit = 10) {
    if (isOfflineRuntime()) return;

    const currentCompany = await resolveActiveCompanyForOperation();
    if (!currentCompany?.id) {
      setVoidedPartUsages([]);
      setVoidedPartUsagesTotal(0);
      return;
    }

    const safeLimit = Math.max(10, Number(limit) || 10);
    const { data, error, count } = await supabase
      .from("part_usages")
      .select("*", { count: "exact" })
      .eq("company_id", currentCompany.id)
      .eq("is_voided", true)
      .order("voided_at", { ascending: false })
      .range(0, safeLimit - 1);

    if (error) {
      console.error("Storno-Historie konnte nicht geladen werden:", error.message);
      return;
    }

    setVoidedPartUsages(data || []);
    setVoidedPartUsagesTotal(count || 0);
  }

  async function loadMoreVoidedPartUsages() {
    if (voidedPartUsagesLoadingMore) return;
    if (voidedPartUsages.length >= voidedPartUsagesTotal) return;

    const currentCompany = await resolveActiveCompanyForOperation();
    if (!currentCompany?.id) return;

    const from = voidedPartUsages.length;
    const to = from + 9;
    setVoidedPartUsagesLoadingMore(true);

    const { data, error, count } = await supabase
      .from("part_usages")
      .select("*", { count: "exact" })
      .eq("company_id", currentCompany.id)
      .eq("is_voided", true)
      .order("voided_at", { ascending: false })
      .range(from, to);

    setVoidedPartUsagesLoadingMore(false);

    if (error) {
      if (isOfflineRuntime() || isNetworkFailure(error)) {
        setOfflineSyncMessage(
          "Offline-Modus aktiv · weitere Daten werden nach Wiederherstellung der Verbindung geladen.",
        );
        return;
      }

      alert(`Weitere Stornos konnten nicht geladen werden: ${error.message}`);
      return;
    }

    setVoidedPartUsages((prev) => [
      ...prev,
      ...(data || []).filter(
        (item) => !prev.some((existing) => existing.id === item.id),
      ),
    ]);
    setVoidedPartUsagesTotal(count || voidedPartUsagesTotal);
  }

