  async function assignDocumentToTicketContext(documentItem: DocumentItem, ticket: Ticket) {
    const activeCompanyId = Number(
      companyData?.id || companyDataRef.current?.id || 0,
    );

    if (
      !activeCompanyId ||
      documentItem.company_id == null ||
      Number(documentItem.company_id) !== activeCompanyId ||
      ticket.company_id == null ||
      Number(ticket.company_id) !== activeCompanyId
    ) {
      alert("Dokument und Ticket müssen zur aktuell angemeldeten Firma gehören.");
      await loadDocuments();
      return;
    }

    const relatedDevice = getDeviceForTicket(ticket);
    const relatedCustomer = getCustomerForTicket(ticket);
    const finalCustomerId =
      ticket.customer_id || relatedCustomer?.id || relatedDevice?.customer_id || documentItem.customer_id || null;

    const { error } = await supabase
      .from("documents")
      .update({
        ticket_id: ticket.id,
        customer_id: finalCustomerId,
        device_id: documentItem.device_id || relatedDevice?.id || null,
      })
      .eq("id", documentItem.id)
      .eq("company_id", activeCompanyId);

    if (error) {
      alert(`Dokument konnte nicht zugeordnet werden: ${error.message}`);
      return;
    }

    await loadDocuments();
    setTicketAkteDocumentSearch("");
    alert("Dokument wurde der Ticket-Akte zugeordnet.");
  }

  async function openDocument(item: DocumentItem) {
    if (isOfflineRuntime()) {
      alert(
        "Die Dokumentinformation ist offline verfügbar. Zum Öffnen der Datei wird eine Internetverbindung benötigt.",
      );
      return;
    }

    const activeCompanyId = Number(
      companyData?.id || companyDataRef.current?.id || 0,
    );

    if (
      !activeCompanyId ||
      item.company_id == null ||
      Number(item.company_id) !== activeCompanyId
    ) {
      alert("Dieses Dokument gehört nicht zur aktuell angemeldeten Firma.");
      await loadDocuments();
      return;
    }

    if (
      userProfile?.role === "customer" &&
      Number(item.customer_id || 0) !== Number(userProfile.customer_id || 0)
    ) {
      alert("Dieses Dokument ist Ihrem Kundenkonto nicht zugeordnet.");
      await loadDocuments();
      return;
    }

    const { data, error } = await supabase.storage
      .from("documents")
      .createSignedUrl(item.file_path, 300);

    if (error || !data?.signedUrl) {
      alert("Datei konnte nicht geöffnet werden.");
      return;
    }

    const fileName = item.file_name.toLowerCase();
    const canPreview =
      fileName.endsWith(".pdf") ||
      fileName.endsWith(".jpg") ||
      fileName.endsWith(".jpeg") ||
      fileName.endsWith(".png") ||
      fileName.endsWith(".webp");

    if (canPreview) {
      setPreviewUrl(data.signedUrl);
      setPreviewName(item.file_name);
      return;
    }

    window.open(data.signedUrl, "_blank");
  }

  function closePreview() {
    setPreviewUrl("");
    setPreviewName("");
  }

  function getInventorySourceFromDocument(item: DocumentItem) {
    const fileName = (item.file_name || "").trim();
    const commercialMatch = fileName.match(/^(Lieferschein|Auftrag)-(.+)\.pdf$/i);

    if (!commercialMatch) return null;

    const sourceType = commercialMatch[1].toLowerCase() === "lieferschein"
      ? "Lieferschein"
      : "Auftrag";
    const sourceNumber = commercialMatch[2]?.trim() || "";

    if (!sourceNumber) return null;

    return { sourceType, sourceNumber };
  }

  async function deleteDocument(item: DocumentItem) {
    if (!canDeleteDocument(item)) {
      alert(documentDeleteLockedReason(item));
      return;
    }

    const inventorySource = getInventorySourceFromDocument(item);
    const deleteQuestion = inventorySource
      ? `${inventorySource.sourceType} wirklich löschen? Zugehörige Lagerbewegungen werden dabei storniert und physisch ausgebuchte Bestände zurückgebucht.`
      : "Datei wirklich löschen?";

    if (!confirm(deleteQuestion)) return;

    if (inventorySource) {
      const rollbackResult = await rollbackInventorySource(
        inventorySource.sourceType,
        inventorySource.sourceNumber,
        `${inventorySource.sourceType} im Dokumentenarchiv gelöscht`,
      );

      if (!rollbackResult.ok) {
        alert(`Dokument wurde nicht gelöscht, weil die Lagerbewegung nicht zurückgebucht werden konnte: ${rollbackResult.error}`);
        return;
      }
    }

    const storageResult = await supabase.storage
      .from("documents")
      .remove([item.file_path]);

    if (storageResult.error) {
      alert(
        inventorySource
          ? "Die Lagerbewegung wurde bereits storniert, aber die Datei konnte nicht gelöscht werden. Bitte den Löschvorgang erneut versuchen."
          : "Datei konnte im Storage nicht gelöscht werden.",
      );
      return;
    }

    const activeCompanyId = Number(
      companyData?.id || companyDataRef.current?.id || 0,
    );

    if (
      !activeCompanyId ||
      item.company_id == null ||
      Number(item.company_id) !== activeCompanyId
    ) {
      alert("Dieses Dokument gehört nicht zur aktuell angemeldeten Firma.");
      await loadDocuments();
      return;
    }

    const tableResult = await supabase
      .from("documents")
      .delete()
      .eq("id", item.id)
      .eq("company_id", activeCompanyId);

    if (tableResult.error) {
      alert(
        inventorySource
          ? "Die Lagerbewegung wurde bereits storniert, aber der Dokumenteintrag konnte nicht gelöscht werden. Bitte den Löschvorgang erneut versuchen."
          : "Datei konnte aus der Tabelle nicht gelöscht werden.",
      );
      return;
    }

    await createDeviceHistory(
      item.device_id,
      "Dokument gelöscht",
      `${item.category}: ${item.file_name}`,
      "Dokument",
    );

    await loadDocuments();
  }

  function getTicketTypeLabel(types = ticketTypes) {
    return types.length > 0 ? types.join(" + ") : "Reparatur";
  }

  function toggleTicketType(typeName: string) {
    setTicketTypes((prev) => {
      if (prev.includes(typeName)) {
        const nextTypes = prev.filter((item) => item !== typeName);
        return nextTypes.length > 0 ? nextTypes : ["Reparatur"];
      }

      return [...prev, typeName];
    });
  }

  function splitTicketIssue(rawIssue: string) {
    const value = String(rawIssue || "").trim();

    if (!value) {
      return {
        types: ["Reparatur"],
        subject: "",
      };
    }

    const separatorIndex = value.indexOf(":");

    if (separatorIndex === -1) {
      return {
        types: ["Reparatur"],
        subject: value,
      };
    }

    const prefix = value.slice(0, separatorIndex).trim();
    const subject = value.slice(separatorIndex + 1).trim();

    const detectedTypes = prefix
      .split("+")
      .map((item) => item.trim())
      .filter((item) => ticketTypeOptions.includes(item));

    return {
      types: detectedTypes.length > 0 ? detectedTypes : ["Reparatur"],
      subject: subject || value,
    };
  }

  async function loadCustomerModelsForManufacturer(manufacturerId: string) {
    const numericManufacturerId = Number(manufacturerId);

    setCustomerManufacturerModels([]);
    setCustomerManufacturerModelsError("");

    if (!numericManufacturerId) return;

    setCustomerManufacturerModelsLoading(true);

    try {
      const { data, error } = await supabase.rpc("customer_device_models_catalog");

      if (error) {
        console.error("Kunden-Modelle für ausgewählten Hersteller konnten nicht geladen werden:", error.message);
        setCustomerManufacturerModelsError(
          "Modelle konnten nicht geladen werden. Bitte erneut versuchen.",
        );
        return;
      }

      const matchingModels = ((data || []) as DeviceModel[])
        .filter(
          (modelItem) =>
            Number(modelItem.manufacturer_id) === numericManufacturerId,
        )
        .sort((a, b) =>
          getDeviceModelDisplayName(a).localeCompare(
            getDeviceModelDisplayName(b),
            "de",
          ),
        );

      setCustomerManufacturerModels(matchingModels);
    } catch (error) {
      console.error("Kunden-Modelle für Hersteller konnten nicht geladen werden:", error);
      setCustomerManufacturerModelsError(
        "Modelle konnten nicht geladen werden. Bitte erneut versuchen.",
      );
    } finally {
      setCustomerManufacturerModelsLoading(false);
    }
  }

